import Accelerate
import Foundation

/// A window function: what a frame is multiplied by before a transform, and what shapes a
/// windowed-sinc filter (§6.4.2).
///
/// ```swift
/// STFT(frame: 2_048, hop: 512, window: .hann)                          // vDSP_hann_window, denormalised
/// STFT(frame: 2_048, hop: 512, window: .kaiser(beta: 8.6))             // computed by the package
/// STFT(frame: 2_048, hop: 512, window: .custom { t in 0.5 - 0.5 * cos(2 * .pi * t) })
/// ```
///
/// The Hann, Hamming and Blackman windows are generated by vDSP, bit for bit (WIN-1). The
/// others are computed by the package in double precision. A window is periodic by default,
/// the form a transform wants; `.symmetric` gives the form a filter design wants.
///
/// A window is a description: an immutable value, usable on any thread, sampled once when a plan is
/// compiled or a filter designed. Sampling allocates, and so do creating, comparing and hashing a
/// custom window: none of that is for the analysis thread.
public struct Window: Hashable, Sendable, CustomStringConvertible {
    /// How vDSP scales its Hann window.
    /// A value, usable on any thread; it does not allocate.
    public enum HannScaling: Hashable, Sendable {
        /// Peak 1: `vDSP_HANN_DENORM`.
        case denormalized
        /// Scaled so that its squares sum to the length: `vDSP_HANN_NORM`.
        case normalized
    }

    enum Shape: Hashable, Sendable {
        case hann(HannScaling)
        case hamming
        case blackman
        case rectangular
        case blackmanHarris
        case kaiser(beta: Double)
        case flatTop
        case gaussian(sigma: Double)
        case custom(CustomShape)
    }

    /// A caller's closure with what makes two of them comparable: their values at 65 probe
    /// points across the frame (WIN-2).
    struct CustomShape: Hashable, Sendable {
        static let probeCount = 65
        let value: @Sendable (Double) -> Double
        let probes: [Double]

        init(_ value: @escaping @Sendable (Double) -> Double) {
            self.value = value
            probes = (0 ..< CustomShape.probeCount).map { value(Double($0) / Double(CustomShape.probeCount - 1)) }
        }

        static func == (lhs: CustomShape, rhs: CustomShape) -> Bool {
            // NaN probes compare by bit pattern, so a window equals itself whatever it returns.
            lhs.probes.map(\.bitPattern) == rhs.probes.map(\.bitPattern)
        }

        func hash(into hasher: inout Hasher) {
            hasher.combine(probes.map(\.bitPattern))
        }
    }

    let shape: Shape
    /// True for the symmetric form, false for the periodic one.
    public let isSymmetric: Bool
    /// True for the first half of the window alone (`vDSP_HALF_WINDOW`).
    public let isHalf: Bool
    /// True when the window's analysis is logged once per attachment (WIN-5).
    public let isLogged: Bool

    init(shape: Shape, isSymmetric: Bool = false, isHalf: Bool = false, isLogged: Bool = false) {
        self.shape = shape
        self.isSymmetric = isSymmetric
        self.isHalf = isHalf
        self.isLogged = isLogged
    }

    // MARK: The vDSP set (WIN-1)

    /// The Hann window with peak 1: `vDSP_hann_window` with `vDSP_HANN_DENORM`.
    public static var hann: Window { Window(shape: .hann(.denormalized)) }

    /// The Hann window in either of vDSP's scalings.
    public static func hann(_ scaling: HannScaling) -> Window { Window(shape: .hann(scaling)) }

    /// The Hamming window: `vDSP_hamm_window`.
    public static var hamming: Window { Window(shape: .hamming) }

    /// The Blackman window: `vDSP_blkman_window`.
    public static var blackman: Window { Window(shape: .blackman) }

    // MARK: The package set

    /// All ones: no window.
    public static var rectangular: Window { Window(shape: .rectangular) }

    /// The four-term Blackman–Harris window, side lobes below −92 dB.
    public static var blackmanHarris: Window { Window(shape: .blackmanHarris) }

    /// The Kaiser window. `beta` trades main-lobe width for side-lobe level: 0 is rectangular,
    /// 8.6 is close to Blackman–Harris.
    public static func kaiser(beta: Double) -> Window { Window(shape: .kaiser(beta: beta)) }

    /// The five-term flat-top window: almost no scalloping loss, for reading amplitudes.
    public static var flatTop: Window { Window(shape: .flatTop) }

    /// A Gaussian centred on the frame. `sigma` is its standard deviation as a fraction of
    /// the frame length, so the shape does not change with the frame size.
    public static func gaussian(sigma: Double) -> Window { Window(shape: .gaussian(sigma: sigma)) }

    /// A window of the caller's: `value(t)` for `t` running from 0 to 1 across the frame. It is
    /// evaluated once, in double precision, when the window is sampled. A window is zero
    /// outside the frame, whatever the closure returns there.
    ///
    /// Two custom windows are equal when their closures agree at 65 probe points across the frame
    /// and they share the periodic or symmetric choice (WIN-2). Creating one evaluates the closure
    /// at those points, which allocates, and comparing or hashing one allocates too.
    public static func custom(_ value: @escaping @Sendable (Double) -> Double) -> Window {
        Window(shape: .custom(CustomShape(value)))
    }

    // MARK: Forms

    /// The symmetric form: the first and the last sample are equal. For the vDSP windows it
    /// is still generated by vDSP, one sample shorter and closed with its first value.
    public var symmetric: Window { Window(shape: shape, isSymmetric: true, isHalf: isHalf, isLogged: isLogged) }

    /// The periodic form, the default: the window is one period of a periodic function.
    public var periodic: Window { Window(shape: shape, isSymmetric: false, isHalf: isHalf, isLogged: isLogged) }

    /// The first half of the window alone: `(count + 1) / 2` samples, as `vDSP_HALF_WINDOW`
    /// gives them.
    public var half: Window { Window(shape: shape, isSymmetric: isSymmetric, isHalf: true, isLogged: isLogged) }

    /// The window with its analysis logged once per attachment (WIN-5). Otherwise nothing is
    /// logged.
    public func logged() -> Window { Window(shape: shape, isSymmetric: isSymmetric, isHalf: isHalf, isLogged: true) }

    /// True for a window vDSP generates.
    public var isGeneratedByVDSP: Bool {
        switch shape {
        case .hann, .hamming, .blackman: true
        default: false
        }
    }

    /// The window as it is written in Swift, `kaiser(beta: 8.6)` or `hann.symmetric` for example; a
    /// custom window is `custom`. It allocates the text it returns.
    public var description: String {
        let name: String
        switch shape {
        case .hann(.denormalized): name = "hann"
        case .hann(.normalized): name = "hann(.normalized)"
        case .hamming: name = "hamming"
        case .blackman: name = "blackman"
        case .rectangular: name = "rectangular"
        case .blackmanHarris: name = "blackmanHarris"
        case .kaiser(let beta): name = "kaiser(beta: \(beta))"
        case .flatTop: name = "flatTop"
        case .gaussian(let sigma): name = "gaussian(sigma: \(sigma))"
        case .custom: name = "custom"
        }
        return name + (isSymmetric ? ".symmetric" : "") + (isHalf ? ".half" : "")
    }

    // MARK: Sampling

    /// The window sampled once, in single precision: `count` values, or `(count + 1) / 2` for
    /// a half window.
    ///
    /// - Throws: `invalidParameter` for a count below 1, a parameter that is not finite, a
    ///   sample that is not finite, and a window that is zero everywhere (WIN-3).
    public func samples(count: Int) throws(DSPError) -> [Float] {
        if isGeneratedByVDSP {
            let values = try generated(count) { (target: UnsafeMutablePointer<Float>, length: Int, flags: Int32) in
                switch shape {
                case .hann(let scaling): vDSP_hann_window(target, vDSP_Length(length), flags | Int32(scaling == .normalized ? vDSP_HANN_NORM : vDSP_HANN_DENORM))
                case .hamming: vDSP_hamm_window(target, vDSP_Length(length), flags)
                default: vDSP_blkman_window(target, vDSP_Length(length), flags)
                }
            }
            return try Window.checked(values)
        }
        return try doubleSamples(count: count).map { Float($0) }
    }

    /// The window sampled once, in double precision.
    public func doubleSamples(count: Int) throws(DSPError) -> [Double] {
        if isGeneratedByVDSP {
            let values = try generated(count) { (target: UnsafeMutablePointer<Double>, length: Int, flags: Int32) in
                switch shape {
                case .hann(let scaling): vDSP_hann_windowD(target, vDSP_Length(length), flags | Int32(scaling == .normalized ? vDSP_HANN_NORM : vDSP_HANN_DENORM))
                case .hamming: vDSP_hamm_windowD(target, vDSP_Length(length), flags)
                default: vDSP_blkman_windowD(target, vDSP_Length(length), flags)
                }
            }
            return try Window.checked(values)
        }
        guard count >= 1 else { throw Window.refused("a window has at least one sample, not \(count)") }
        let evaluate = try function()
        // t = n / N for the periodic form, n / (N − 1) for the symmetric one.
        let span = Double(isSymmetric ? max(count - 1, 1) : count)
        let length = isHalf ? (count + 1) / 2 : count
        var values = [Double](repeating: 0, count: length)
        for index in 0 ..< length { values[index] = evaluate(Double(index) / span) }
        return try Window.checked(values)
    }

    /// A vDSP window of `count` samples in the form asked for.
    private func generated<Value: BinaryFloatingPoint>(
        _ count: Int, _ generate: (UnsafeMutablePointer<Value>, Int, Int32) -> Void
    ) throws(DSPError) -> [Value] {
        guard count >= 1 else { throw Window.refused("a window has at least one sample, not \(count)") }
        let flags = Int32(isHalf ? vDSP_HALF_WINDOW : 0)
        let kept = isHalf ? (count + 1) / 2 : count
        guard isSymmetric else {
            var values = [Value](repeating: 0, count: count)
            values.withUnsafeMutableBufferPointer { generate($0.baseAddress!, count, flags) }
            return Array(values.prefix(kept))
        }
        // Symmetric: the periodic window one sample shorter, closed with its first value.
        guard count > 1 else { return [1] }
        var values = [Value](repeating: 0, count: count)
        values.withUnsafeMutableBufferPointer { generate($0.baseAddress!, count - 1, 0) }
        values[count - 1] = values[0]
        return Array(values.prefix(kept))
    }

    /// The window as a function of `t` in `0 … 1`, for the shapes the package computes.
    private func function() throws(DSPError) -> (Double) -> Double {
        switch shape {
        case .rectangular:
            return { _ in 1 }
        case .blackmanHarris:
            return { t in 0.35875 - 0.48829 * cos(2 * .pi * t) + 0.14128 * cos(4 * .pi * t) - 0.01168 * cos(6 * .pi * t) }
        case .flatTop:
            return { t in
                0.21557895 - 0.41663158 * cos(2 * .pi * t) + 0.277263158 * cos(4 * .pi * t) - 0.083578947 * cos(6 * .pi * t)
                    + 0.006947368 * cos(8 * .pi * t)
            }
        case .kaiser(let beta):
            guard beta.isFinite, beta >= 0 else { throw Window.refused("the beta of a Kaiser window is finite and not negative, not \(beta)") }
            let scale = Window.besselI0(beta)
            return { t in
                let x = 2 * t - 1
                return Window.besselI0(beta * max(1 - x * x, 0).squareRoot()) / scale
            }
        case .gaussian(let sigma):
            guard sigma.isFinite, sigma > 0 else { throw Window.refused("the sigma of a Gaussian window is positive and finite, not \(sigma)") }
            return { t in
                let x = (t - 0.5) / sigma
                return exp(-0.5 * x * x)
            }
        case .custom(let custom):
            return custom.value
        case .hann, .hamming, .blackman:
            throw Window.refused("\(self) is generated by vDSP")
        }
    }

    /// The modified Bessel function of the first kind, order 0, by its power series: every
    /// term is positive, so the sum loses nothing to cancellation.
    static func besselI0(_ x: Double) -> Double {
        let quarter = x * x / 4
        var term = 1.0, sum = 1.0
        var k = 1.0
        while k < 500 {
            term *= quarter / (k * k)
            sum += term
            if term < sum * 1e-17 { break }
            k += 1
        }
        return sum
    }

    private static func refused(_ reason: String) -> DSPError {
        .invalidParameter(stage: .none, parameter: "window", reason: reason)
    }

    /// WIN-3: a sample that is not finite, or a window that is zero everywhere, is an error.
    private static func checked<Value: BinaryFloatingPoint>(_ values: [Value]) throws(DSPError) -> [Value] {
        if let index = values.firstIndex(where: { !$0.isFinite }) {
            throw refused("sample \(index) of the window is \(values[index]), which is not a finite number")
        }
        guard values.contains(where: { $0 != 0 }) else { throw refused("the window is zero everywhere") }
        return values
    }
}
